changeSet.sql:
SET @fk := (SELECT CONSTRAINT_NAME FROM information_schema.KEY_COLUMN_USAGE
            WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'place'
              AND COLUMN_NAME = 'master_place_id' AND REFERENCED_TABLE_NAME IS NOT NULL LIMIT 1);
SET @stmt := IF(@fk IS NULL, 'SELECT 1', CONCAT('ALTER TABLE place DROP FOREIGN KEY ', @fk));
PREPARE drop_fk FROM @stmt;
EXECUTE drop_fk;
DEALLOCATE PREPARE drop_fk;
